import React, { useState, useEffect } from 'react';

function App() {
  const [simOutput, setSimOutput] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [fileName, setFileName] = useState('');
  const [graphicsStatus, setGraphicsStatus] = useState(null);
  const [backendStatus, setBackendStatus] = useState('checking');
  const [backendInfo, setBackendInfo] = useState(null);

  // Step-by-step simulation state
  const [processId, setProcessId] = useState(null);
  const [isStepping, setIsStepping] = useState(false);
  const [hasSimulationEnded, setHasSimulationEnded] = useState(false);
  const [stepCount, setStepCount] = useState(0);

  // Check backend health on component mount
  useEffect(() => {
    checkBackendHealth();
  }, []);

  const checkBackendHealth = async () => {
    try {
      const response = await fetch('http://localhost:5001/health');
      if (response.ok) {
        const data = await response.json();
        setBackendInfo(data);

        if (data.executable_found) {
          setBackendStatus('ready');
        } else if (data.cpp_source_found && data.compiler_available) {
          setBackendStatus('needs-compile');
        } else if (data.cpp_source_found && !data.compiler_available) {
          setBackendStatus('no-compiler');
        } else {
          setBackendStatus('no-source');
        }
      } else {
        setBackendStatus('error');
      }
    } catch (error) {
      setBackendStatus('offline');
    }
  };

  const handleCompile = async () => {
    setLoading(true);
    setGraphicsStatus("🔨 Compiling simulator...");

    try {
      const response = await fetch('http://localhost:5001/compile', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || `Compilation failed: ${response.statusText}`);
      }

      const result = await response.json();
      setGraphicsStatus(`✅ ${result.message}`);

      // Refresh backend status after compilation
      setTimeout(() => {
        checkBackendHealth();
      }, 1000);

    } catch (error) {
      console.error('Compilation error:', error);
      setGraphicsStatus(`❌ Compilation failed: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate file extension
    if (!file.name.toLowerCase().endsWith('.bin')) {
      alert('Please select a .bin file');
      return;
    }

    setSelectedFile(file);
    setFileName(file.name);
    setSimOutput('');
    setGraphicsStatus(null);
    // Reset step-by-step state
    setProcessId(null);
    setIsStepping(false);
    setHasSimulationEnded(false);
    setStepCount(0);
  };

  const handleRunSimulation = async (mode) => {
    if (!selectedFile) {
      alert("Please upload a .bin file first.");
      return;
    }

    if (backendStatus !== 'ready') {
      alert("Backend is not ready. Please check if the simulator executable is available.");
      return;
    }

    const formData = new FormData();
    formData.append('binfile', selectedFile);
    formData.append('mode', mode);

    setLoading(true);
    setSimOutput('');
    setGraphicsStatus(null);
    setHasSimulationEnded(false);
    setStepCount(0);

    try {
      const response = await fetch('http://localhost:5001/simulate', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      if (mode === 'full') {
        const result = await response.text();
        setSimOutput(result);
        setGraphicsStatus("✅ Full simulation completed");
        setHasSimulationEnded(true);
      } else if (mode === 'step') {
        const result = await response.json();
        if (result.error) {
          throw new Error(result.error);
        }
        setProcessId(result.process_id);
        setIsStepping(true);
        setSimOutput(`🚶 Step-by-step simulation started (Process ID: ${result.process_id})\n\n${result.initial_output}`);
        setGraphicsStatus("🎯 Ready for step-by-step execution - Click 'Next Step' to proceed");
      }

    } catch (error) {
      console.error('Simulation error:', error);
      setSimOutput(`❌ Error: ${error.message}`);
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true);
      setGraphicsStatus("❌ Simulation failed");
    } finally {
      setLoading(false);
    }
  };

  const handleNextStep = async () => {
    if (!processId) return;

    setLoading(true);
    setGraphicsStatus("⏳ Executing next step...");

    try {
      const response = await fetch('http://localhost:5001/step_simulation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          process_id: processId,
          command: '\n' // Send newline to continue to next step
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      const result = await response.json();

      // Append new output to existing output
      if (result.output && result.output.trim()) {
        setSimOutput(prevOutput =>
            prevOutput + `\n\n--- Step ${result.step_count} ---\n${result.output}`
        );
      } else {
        setSimOutput(prevOutput =>
            prevOutput + `\n\n--- Step ${result.step_count} --- (No output)`
        );
      }

      setStepCount(result.step_count);

      if (result.terminated) {
        setSimOutput(prevOutput =>
            prevOutput + `\n\n🏁 Simulation completed after ${result.step_count} steps.`
        );
        setProcessId(null);
        setIsStepping(false);
        setHasSimulationEnded(true);
        setGraphicsStatus(`✅ Simulation completed in ${result.step_count} steps`);
      } else {
        setGraphicsStatus(`🎯 Step ${result.step_count} completed - Ready for next step`);
      }

    } catch (error) {
      console.error('Step execution error:', error);
      setSimOutput(prevOutput =>
          prevOutput + `\n\n❌ Error during step execution: ${error.message}`
      );
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true);
      setGraphicsStatus("❌ Step execution failed");
    } finally {
      setLoading(false);
    }
  };

  const handleStopSimulation = async () => {
    if (!processId) return;

    setLoading(true);
    setGraphicsStatus("⏳ Stopping simulation...");

    try {
      const response = await fetch('http://localhost:5001/end_simulation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ process_id: processId }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      const result = await response.json();
      setSimOutput(prevOutput =>
          prevOutput + `\n\n⏹️ ${result.status || "Simulation stopped by user"}`
      );
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true);
      setGraphicsStatus(`⏹️ Simulation stopped after ${stepCount} steps`);

    } catch (error) {
      console.error('Stop simulation error:', error);
      setSimOutput(prevOutput =>
          prevOutput + `\n\n❌ Error stopping simulation: ${error.message}`
      );
      setGraphicsStatus("❌ Error stopping simulation");
    } finally {
      setLoading(false);
    }
  };

  const handleClear = async () => {
    // If there's an active simulation, stop it first
    if (isStepping && processId) {
      await handleStopSimulation();
    }

    setSimOutput('');
    setSelectedFile(null);
    setFileName('');
    setGraphicsStatus(null);
    setProcessId(null);
    setIsStepping(false);
    setHasSimulationEnded(false);
    setStepCount(0);
  };

  const getBackendStatusDisplay = () => {
    switch (backendStatus) {
      case 'ready':
        return '✅ Backend ready - Simulator executable found';
      case 'needs-compile':
        return '🔨 Backend online - Source found, needs compilation';
      case 'no-compiler':
        return '❌ Backend online - Source found but no g++ compiler';
      case 'no-source':
        return '❌ Backend online - No z16sim.cpp source file found';
      case 'offline':
        return '❌ Backend offline';
      case 'error':
        return '❌ Backend error';
      default:
        return '🔄 Checking backend...';
    }
  };

  const getBackendDetails = () => {
    if (!backendInfo) return null;

    return (
        <div style={{ fontSize: '12px', color: '#666', marginTop: '5px' }}>
          <div>Active simulations: {backendInfo.active_simulations}</div>
          <div>Source file: {backendInfo.cpp_source_found ? '✅' : '❌'}</div>
          <div>Compiler: {backendInfo.compiler_available ? '✅' : '❌'}</div>
          {backendInfo.executable_path && (
              <div>Executable: {backendInfo.executable_path}</div>
          )}
        </div>
    );
  };

  return (
      <div style={{
        maxWidth: '800px',
        margin: '0 auto',
        padding: '20px',
        fontFamily: 'Arial, sans-serif'
      }}>
        <h2 style={{ textAlign: 'center', marginBottom: '20px' }}>
          ⚙️ ZX16 Simulator Interface
        </h2>

        {/* Backend Status */}
        <div style={{
          marginBottom: '20px',
          padding: '12px',
          backgroundColor: backendStatus === 'ready' ? '#e8f5e8' :
              backendStatus === 'needs-compile' ? '#fff3cd' : '#ffebee',
          border: '1px solid #ddd',
          borderRadius: '8px',
          fontSize: '14px'
        }}>
          <div style={{ fontWeight: 'bold', marginBottom: '5px' }}>
            {getBackendStatusDisplay()}
          </div>
          {getBackendDetails()}

          <div style={{ marginTop: '10px' }}>
            {backendStatus === 'offline' && (
                <button
                    onClick={checkBackendHealth}
                    style={{
                      padding: '4px 12px',
                      fontSize: '12px',
                      backgroundColor: '#007bff',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                >
                  🔄 Retry Connection
                </button>
            )}

            {backendStatus === 'needs-compile' && (
                <button
                    onClick={handleCompile}
                    disabled={loading}
                    style={{
                      padding: '4px 12px',
                      fontSize: '12px',
                      backgroundColor: '#ff9800',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: loading ? 'not-allowed' : 'pointer'
                    }}
                >
                  {loading ? '🔨 Compiling...' : '🔨 Compile Simulator'}
                </button>
            )}
          </div>
        </div>

        {/* File Upload Section */}
        <div style={{ marginBottom: '20px' }}>
          <input
              type="file"
              accept=".bin"
              onChange={handleFileChange}
              disabled={backendStatus !== 'ready'}
              style={{
                padding: '8px',
                border: '1px solid #ddd',
                borderRadius: '4px',
                width: '100%'
              }}
          />
          {fileName && (
              <p style={{
                marginTop: '8px',
                fontSize: '14px',
                color: '#666',
                fontStyle: 'italic'
              }}>
                📄 Selected: {fileName}
              </p>
          )}
        </div>

        {/* Button Group */}
        <div style={{
          display: 'flex',
          gap: '10px',
          flexWrap: 'wrap',
          marginBottom: '20px'
        }}>
          {/* Show simulation start buttons when not stepping */}
          {!isStepping && (
              <>
                <button
                    onClick={() => handleRunSimulation('full')}
                    disabled={loading || !selectedFile || backendStatus !== 'ready'}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#28a745',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: (loading || !selectedFile || backendStatus !== 'ready') ? 'not-allowed' : 'pointer',
                      opacity: (loading || !selectedFile || backendStatus !== 'ready') ? 0.6 : 1
                    }}
                >
                  ▶️ {loading ? 'Running Full...' : 'Run Full Simulation'}
                </button>
                <button
                    onClick={() => handleRunSimulation('step')}
                    disabled={loading || !selectedFile || backendStatus !== 'ready'}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#007bff',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: (loading || !selectedFile || backendStatus !== 'ready') ? 'not-allowed' : 'pointer',
                      opacity: (loading || !selectedFile || backendStatus !== 'ready') ? 0.6 : 1
                    }}
                >
                  🚶 {loading ? 'Starting Step...' : 'Run Step-by-Step'}
                </button>
              </>
          )}

          {/* Show step control buttons when stepping */}
          {isStepping && !hasSimulationEnded && (
              <>
                <button
                    onClick={handleNextStep}
                    disabled={loading}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#17a2b8',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: loading ? 'not-allowed' : 'pointer',
                      opacity: loading ? 0.6 : 1
                    }}
                >
                  ➡️ {loading ? 'Stepping...' : `Next Step (${stepCount + 1})`}
                </button>
                <button
                    onClick={handleStopSimulation}
                    disabled={loading}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#dc3545',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: loading ? 'not-allowed' : 'pointer',
                      opacity: loading ? 0.6 : 1
                    }}
                >
                  ⏹️ Stop Simulation
                </button>
              </>
          )}

          <button
              onClick={handleClear}
              disabled={loading}
              style={{
                padding: '10px 20px',
                backgroundColor: '#6c757d',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: loading ? 'not-allowed' : 'pointer',
                opacity: loading ? 0.6 : 1
              }}
          >
            🧹 Clear
          </button>
        </div>

        {/* Status Display */}
        {graphicsStatus && (
            <div style={{
              marginBottom: '20px',
              padding: '12px',
              backgroundColor: '#e7f3ff',
              border: '1px solid #b3d9ff',
              borderRadius: '8px',
              fontWeight: 'bold',
              fontSize: '14px'
            }}>
              {graphicsStatus}
            </div>
        )}

        {/* Output Display */}
        {simOutput && (
            <div>
              <h3 style={{ marginBottom: '10px' }}>📋 Simulation Output:</h3>
              <pre style={{
                whiteSpace: 'pre-wrap',
                maxHeight: '500px',
                overflowY: 'auto',
                border: '1px solid #ddd',
                padding: '15px',
                backgroundColor: '#f8f9fa',
                fontSize: '13px',
                fontFamily: 'Consolas, Monaco, "Courier New", monospace',
                borderRadius: '8px',
                lineHeight: '1.4'
              }}>
            {simOutput}
          </pre>
            </div>
        )}
      </div>
  );
}

export default App;
